/*
 * Per-network marshal block: normalize/quantize to the hls4ml network and
 * denormalize the result back to physical units.
 *
 * All per-network constants come from nn_marshal_config.h in the deployed
 * network folder (auto-generated by generate_nn_marshal_config.py).
 */

#include "nn_marshal.h"

#include "nn_marshal_config.h"
#include "../nn_fixed_format.h"

static ap_uint<32> normalize_quantize(float x, int idx)
{
    const float y = NN_NORM_A[idx] * x + NN_NORM_B[idx];
    return nn_fixed_quantize_input(y);
}

static float denormalize(ap_uint<32> code)
{
    const float val = nn_fixed_dequantize_output(code);
    return NN_DENORM_A[0] * val + NN_DENORM_B[0];
}

static void read_gate_request(
    hls::stream<secloc_axis32_t>& gate_req,
    float inputs[NN_IO_INPUT_COUNT])
{
READ_GATE:
    for (int i = 0; i < NN_IO_INPUT_COUNT; ++i) {
#pragma HLS PIPELINE II=1
        secloc_axis32_t beat = gate_req.read();
        inputs[i] = secloc_bits_to_float(beat.data);
    }
}

static void write_gate_response(
    hls::stream<secloc_axis32_t>& gate_resp,
    float Q)
{
    gate_resp.write(secloc_make_beat(secloc_float_to_bits(Q), true));
}

static void send_nn_request(
    hls::stream<secloc_axis32_t>& nn_req,
    const float inputs[NN_IO_INPUT_COUNT])
{
NN_REQ:
    for (int i = 0; i < NN_IO_INPUT_COUNT; ++i) {
#pragma HLS PIPELINE II=1
        bool last = (i == NN_IO_INPUT_COUNT - 1);
        nn_req.write(secloc_make_beat(normalize_quantize(inputs[i], i), last));
    }
}

static bool wait_nn_response(
    hls::stream<secloc_axis32_t>& nn_resp,
    ap_uint<32>* code_out)
{
    secloc_axis32_t resp = nn_resp.read();
    *code_out = nn_fixed_extract_output_code(resp.data);
    return true;
}

void nn_marshal_handle_transaction(
    hls::stream<secloc_axis32_t>& gate_req,
    hls::stream<secloc_axis32_t>& gate_resp,
    hls::stream<secloc_axis32_t>& nn_req,
    hls::stream<secloc_axis32_t>& nn_resp)
{
    float inputs[NN_IO_INPUT_COUNT];
    read_gate_request(gate_req, inputs);
    send_nn_request(nn_req, inputs);

    ap_uint<32> code = 0;
    (void)wait_nn_response(nn_resp, &code);
    write_gate_response(gate_resp, denormalize(code));
}

void nn_marshal(
    hls::stream<secloc_axis32_t>& gate_req,
    hls::stream<secloc_axis32_t>& gate_resp,
    hls::stream<secloc_axis32_t>& nn_req,
    hls::stream<secloc_axis32_t>& nn_resp)
{
#pragma HLS INTERFACE axis port=gate_req
#pragma HLS INTERFACE axis port=gate_resp
#pragma HLS INTERFACE axis port=nn_req
#pragma HLS INTERFACE axis port=nn_resp
#pragma HLS INTERFACE ap_ctrl_none port=return

MARSHAL_LOOP:
    while (true) {
#pragma HLS PIPELINE off
        nn_marshal_handle_transaction(gate_req, gate_resp, nn_req, nn_resp);
    }
}
